];
const key = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/ς/g,'σ');
const words = new Map(rows.map(r => [key(r[0]),r]));
const input=document.getElementById('word');
function show(){
 const value=input.value.trim(); const row=words.get(key(value));
 document.getElementById('form').textContent=row ? row[0] : value ? 'Example not listed' : 'Choose an example';
 document.getElementById('group').textContent=row ? row[1] : value ? 'No accent prediction' : 'Compare a rule with its qualifications.';
 document.getElementById('reason').textContent=row ? row[2] : value ? 'Use one of the passage examples above. An ending by itself does not establish meaning, formation or accent.' : 'The passage treats meaning, word formation and particular names together.';
