 ['ἀχίτων','Composition raises the accent.'],
 ['μακραίων','Composition raises the accent.'],
 ['αὐτόχθων','Composition raises the accent.'],
 ['Ἀμφίων','A participle used as a proper name shifts its accent.'],
 ['Ὑπερίων','A participle used as a proper name shifts its accent.']
];
const key=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/ς/g,'σ');
const examples=new Map(rows.map(r=>[key(r[0]),r]));
const $=s=>document.querySelector(s), input=$('#in');
function contextForm(s){
 return s.replace(/([\p{L}\p{M}]+)([^\p{L}\p{M}]*)$/u,(all,word,punct)=>{
   const d=word.normalize('NFD');
   return (/[.,;:!?··]/u.test(punct) ? d : d.replace(/ω\u0301ν$/u,'ω\u0300ν')).normalize('NFC')+punct;
 });
}
function render(){
 const raw=input.value.trim();
 const match=raw.match(/^([^\p{L}\p{M}]*)([\p{L}\p{M}]+)([^\p{L}\p{M}]*)$/u);
 const row=match ? examples.get(key(match[2])) : null;
 const result=row ? match[1]+row[0]+match[3] : raw;
 $('#out').textContent=result||'—';
 $('#grave').textContent=row ? contextForm(result) : result||'—';
 const base=match ? key(match[2]) : '';
 $('#ending').textContent=base.endsWith('ιων') ? '-ιων' : base.endsWith('ων') ? '-ων' : '—';
 $('#explanation').textContent=row ? row[1] : raw ? 'Not in the cited example set: no accent prediction. Try a listed example.' : 'Choose an example to see its rule.';
}
$('#go').addEventListener('click',render);
input.addEventListener('keydown',e=>{if(e.key==='Enter')render();});
document.querySelectorAll('.ex').forEach(el=>el.addEventListener('click',()=>{input.value=el.dataset.fill;render();input.focus();}));
$('#clear').addEventListener('click',()=>{input.value='';render();$('#qmsg').textContent='—';input.focus();});
document.querySelectorAll('.qbtn').forEach(btn=>{
 const row=examples.get(key(btn.textContent.trim()));
 if(row)btn.textContent=row[0];
 btn.addEventListener('click',()=>{
   input.value=btn.textContent;render();
   const ok=btn.dataset.answer==='1';
   $('#qmsg').textContent=ok ? 'Correct: this cited form has a final acute.' : 'This cited form has a non-final acute; it is barytone.';
   $('#qmsg').style.color=ok ? 'var(--good)' : 'var(--warn)';
 });
});
render();
})();

